mapper.select:
-- Select subscription plan list.
SELECT

FROM subscription_plans sp

ORDER BY sp.sort_order ASC, sp.plan_code ASC
LIMIT #{size}
OFFSET #{offset}

-- Select user subscriptions. SELECT
FROM user_subscriptions us INNER JOIN subscription_plans sp ON sp.id = us.plan_id
ORDER BY us.created_at DESC, us.id DESC LIMIT #{size} OFFSET #{offset}

-- Select payment transactions.
SELECT

FROM payment_transactions pt

ORDER BY pt.created_at DESC, pt.id DESC
LIMIT #{size}
OFFSET #{offset}

-- Select refund transactions.
SELECT

FROM refund_transactions rt

ORDER BY rt.created_at DESC, rt.id DESC
LIMIT #{size}
OFFSET #{offset}
